sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 rmix;
layout(color) uniform half4 gmix;
layout(color) uniform half4 bmix;
uniform float gamma;
uniform float offset;

half4 main(float2 coord) {
    half4 col = image.eval(coord);
    if (col.a < 1e-3) return half4(0);
    float3 rgb = float3(col.rgb / col.a);
    float3 mixed = float3(dot(rgb, float3(rmix.rgb)), dot(rgb, float3(gmix.rgb)), dot(rgb, float3(bmix.rgb)));
    float g = max(gamma, 0.01);
    float3 outRgb = pow(max(mixed, float3(0.0)), float3(1.0 / g)) + offset;
    outRgb = clamp(outRgb, 0.0, 1.0);
    return half4(half3(outRgb) * col.a, col.a);
}
